import { jsx as _jsx } from "react/jsx-runtime";
import { useService, WixServices } from '@wix/services-manager-react';
import { createServicesMap } from '@wix/services-manager';
import { ServiceListServiceDefinition, ServiceListService, } from '../../../services/service-list/service-list.js';
/**
 * Root component that provides ServiceList service context.
 *
 * @component
 * @example
 * ```tsx
 * <ServiceList.Root serviceListConfig={{ services: myServices }}>
 *   {children}
 * </ServiceList.Root>
 * ```
 */
export function Root(props) {
    return (_jsx(WixServices, { servicesMap: createServicesMap().addService(ServiceListServiceDefinition, ServiceListService, props.serviceListConfig), disposeOnUnmount: true, children: props.children }));
}
/**
 * Component that provides services list data through render props.
 * Exposes services, loading state, error, query options, and pagination metadata (including hasNext flag).
 *
 * @component
 * @example
 * ```tsx
 * <ServiceList.Services>
 *   {({ services, isLoading, error, pagingMetadata }) => {
 *     if (isLoading) return <div>Loading...</div>;
 *     if (error) return <div>Error: {error}</div>;
 *     return (
 *       <div>
 *         {services.map(service => (
 *           <div key={service._id}>{service.name}</div>
 *         ))}
 *         {pagingMetadata.hasNext && (
 *           <button>Load More Services</button>
 *         )}
 *       </div>
 *     );
 *   }}
 * </ServiceList.Services>
 * ```
 */
export function Services(props) {
    const serviceListService = useService(ServiceListServiceDefinition);
    const services = serviceListService.servicesSignal.get();
    const isLoading = serviceListService.isLoadingSignal.get();
    const error = serviceListService.errorSignal.get();
    const queryOptions = serviceListService.queryOptionsSignal.get();
    const pagingMetadata = serviceListService.pagingMetadataSignal.get();
    const hasMore = serviceListService.hasMoreServicesSignal.get();
    const loadMore = serviceListService.actions.loadMore;
    return props.children({
        services,
        isLoading,
        error,
        queryOptions,
        pagingMetadata,
        hasMore,
        loadMore,
    });
}
